/* =====================================================
   DECENTRALIZED VOTING SYSTEM – OFFCHAIN (LUCID)
   Compatible with your Plutus V2 validator
===================================================== */

import {
  Lucid,
  Blockfrost,
  Data,
  Constr,
} from "https://unpkg.com/lucid-cardano@0.10.11/web/mod.js";

/* =====================================================
   CONFIG
===================================================== */

const BLOCKFROST_URL =
  "https://cardano-preprod.blockfrost.io/api/v0";
const BLOCKFROST_KEY =
  "preprodZ36S2oW9axXhXDnsy9Urwi3cHPstxaG1";
const NETWORK = "Preprod";

/* =====================================================
   SCRIPT (CBOR FROM voting_system.cbor)
===================================================== */

const SCRIPT_CBOR = "";

const script = {
  type: "PlutusV2",
  script: SCRIPT_CBOR,
};

/* =====================================================
   ENUMS (ORDER MUST MATCH HASKELL)
===================================================== */

const VoterRole = {
  Admin: 0,
  PrimaryVoter: 1,
  GeneralVoter: 2,
  Pending: 3,
};

const VoterState = {
  Registered: 0,
  Approved: 1,
  Rejected: 2,
  Suspended: 3,
  Voted: 4,
};

const SessionState = {
  Setup: 0,
  Active: 1,
  Tallying: 2,
  Closed: 3,
};

const VotingSystem = {
  SingleChoice: 0,
  MultipleChoice: 1,
  RankedChoice: 2,
};

/* =====================================================
   DATUM SCHEMA
===================================================== */

const VoterRecord = Data.Object({
  vrPubKeyHash: Data.Bytes(),
  vrRole: Data.Integer(),
  vrState: Data.Integer(),
  vrHasVoted: Data.Boolean(),
  vrDelegate: Data.Nullable(Data.Bytes()),
  vrVoteWeight: Data.Integer(),
});

const VotingDatum = Data.Object({
  vdAdmins: Data.Array(Data.Bytes()),
  vdRequiredSigs: Data.Integer(),
  vdVoters: Data.Array(VoterRecord),
  vdSessionState: Data.Integer(),
  vdVotingSystem: Data.Integer(),
  vdOptions: Data.Array(Data.Bytes()),
  vdVoteCounts: Data.Array(Data.Integer()),
  vdStartTime: Data.Integer(),
  vdEndTime: Data.Integer(),
  vdMinVotes: Data.Integer(),
  vdMaxChoices: Data.Integer(),
});

/* =====================================================
   REDEEMERS (VotingAction)
===================================================== */

const Redeemer = {
  CreateSession: Data.to(new Constr(0, [])),
  RegisterVoter: Data.to(new Constr(1, [])),
  ApproveVoter: (pkh) =>
    Data.to(new Constr(2, [pkh])),
  RejectVoter: (pkh) =>
    Data.to(new Constr(3, [pkh])),
  CastVote: (choices) =>
    Data.to(new Constr(4, [choices.map(BigInt)])),
  CloseVoting: Data.to(new Constr(5, [])),
  TallyVotes: Data.to(new Constr(6, [])),
  UpdateAdmin: (pkh, add) =>
    Data.to(new Constr(7, [pkh, add])),
};

/* =====================================================
   GLOBAL STATE
===================================================== */

let lucid;
let walletAddress;
let walletPkh;
let scriptAddress;

/* =====================================================
   INIT
===================================================== */

export async function init() {
  lucid = await Lucid.new(
    new Blockfrost(BLOCKFROST_URL, BLOCKFROST_KEY),
    NETWORK
  );

  const api = await window.cardano.lace.enable();
  lucid.selectWallet(api);

  walletAddress = await lucid.wallet.address();
  walletPkh =
    lucid.utils.getAddressDetails(walletAddress)
      .paymentCredential.hash;

  scriptAddress =
    lucid.utils.validatorToAddress(script);

  console.log("Wallet:", walletAddress);
  console.log("Script:", scriptAddress);
}

/* =====================================================
   CREATE SESSION
===================================================== */

export async function createSession({
  options,
  startTime,
  endTime,
}) {
  const datum = Data.to({
    vdAdmins: [walletPkh],
    vdRequiredSigs: 1n,
    vdVoters: [],
    vdSessionState: SessionState.Setup,
    vdVotingSystem: VotingSystem.SingleChoice,
    vdOptions: options.map(
      (o) => new TextEncoder().encode(o)
    ),
    vdVoteCounts: options.map(() => 0n),
    vdStartTime: BigInt(startTime),
    vdEndTime: BigInt(endTime),
    vdMinVotes: 1n,
    vdMaxChoices: 1n,
  }, VotingDatum);

  const tx = await lucid
    .newTx()
    .payToContract(
      scriptAddress,
      { inline: datum },
      { lovelace: 2_000_000n }
    )
    .addSignerKey(walletPkh)
    .complete();

  return (await tx.sign().complete()).submit();
}

/* =====================================================
   REGISTER VOTER
===================================================== */

export async function registerVoter() {
  const utxo = (await lucid.utxosAt(scriptAddress))[0];

  const tx = await lucid
    .newTx()
    .collectFrom([utxo], Redeemer.RegisterVoter)
    .attachSpendingValidator(script)
    .payToContract(
      scriptAddress,
      { inline: utxo.datum },
      utxo.assets
    )
    .addSignerKey(walletPkh)
    .complete();

  return (await tx.sign().complete()).submit();
}

/* =====================================================
   APPROVE / REJECT VOTER (ADMIN)
===================================================== */

